CREATE OR REPLACE FUNCTION public._q74_run_suite(_script text) RETURNS text LANGUAGE plpgsql SECURITY INVOKER SET search_path TO public AS $$ BEGIN BEGIN EXECUTE _script; RETURN 'NO EXCEPTION'; EXCEPTION WHEN others THEN RETURN SQLERRM; END; END $$; REVOKE ALL ON FUNCTION public._q74_run_suite(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public._q74_run_suite(text) TO service_role;